import { test, expect } from '@playwright/test';
import path from 'node:path';

test.use({ storageState: path.join(__dirname, '../../auth/user.json') });

test.describe('Наведение камеры', () => {
  test('Ручная разметка + подтверждение разблокируют «המשך» при noWater #7076cfab @iphone @prod-safe', async ({ page }) => {
    // 1. Подготовка с ?mock=noWater до шага камеры; дождаться подсказки «לא רואים מים».
    await page.goto('/home?mock=noWater');
    await page.getByRole('button', { name: 'התחלת ניטור' }).click();
    await page.getByRole('button', { name: 'עוצמת צפצוף מקסימלית' }).click();
    await page.getByRole('button', { name: 'השמעה' }).click();
    await page.getByRole('button', { name: 'שמעתי' }).click();
    await page.getByRole('button', { name: 'המשך' }).click();
    await page.waitForURL(/\/monitor\/camera/);
    await expect(page.getByText('לא רואים מים')).toBeVisible({ timeout: 20_000 });

    // 2. Проверить, что «המשך» неактивна.
    const continueButton = page.getByRole('button', { name: 'המשך' });
    await expect(continueButton).toHaveAttribute('aria-disabled', 'true');

    // 3. Нажать «סימון ידני של שטח המים».
    await page.getByRole('button', { name: 'סימון ידני של שטח המים' }).click();

    // 4. Проверить «המשך» до галочки; отметить подтверждение.
    await expect(continueButton).toHaveAttribute('aria-disabled', 'true');
    await page.getByRole('checkbox', { name: /ושום דבר לא מסתיר אותו/ }).click();
    await expect(continueButton).not.toHaveAttribute('aria-disabled', 'true');

    // 5. Нажать «המשך».
    await continueButton.click();
    await page.waitForURL(/\/monitor\/children/);
  });
});
